// Run manually with the Natural Earth GeoJSON path. The app bundles the generated data.
// UN Geospatial boundaries, hosted by UNEP-WCMC. Query layer 6 in WGS84 GeoJSON,
// with maxAllowableOffset=0.06. Attribution and the source URL remain in the generated file.
const fs = require('node:fs'), path = require('node:path'), crypto = require('node:crypto');
const source = fs.readFileSync(process.argv[2]);
const data = JSON.parse(source);
const round = value => Math.round(value * 10) / 10;
const codes = require('../src/assets/worldCountryCodes.json');
const countries = data.features.filter(feature => (feature.properties.iso3cd || feature.properties.ISO_A2_EH) !== 'ATA' && feature.properties.ISO_A2_EH !== 'AQ').map(feature => {
    const p = feature.properties;
    const polygons = feature.geometry.type === 'Polygon' ? [feature.geometry.coordinates] : feature.geometry.coordinates;
    const outline = polygons.flatMap(polygon => polygon.map(ring => {
        const points = ring.map(([lon, lat]) => `${round((lon + 180) / 360 * 1000)},${round((85 - lat) / 145 * 470)}`).filter((point, index, all) => index === 0 || point !== all[index - 1]);
        const coordinates = points.map(point => point.split(',').map(value => Math.round(Number(value) * 10)));
        let [x, y] = coordinates[0];
        const deltas = coordinates.slice(1).map(([nextX, nextY]) => {
            const delta = `${(nextX - x) / 10},${(nextY - y) / 10}`; x = nextX; y = nextY; return delta;
        });
        return `M${coordinates[0][0] / 10},${coordinates[0][1] / 10}${deltas.length ? 'l' + deltas.join(' ') : ''}Z`;
    })).join('');
    return { code: codes[p.iso3cd] || (p.ISO_A2_EH === '-99' ? p.ADM0_A3 : p.ISO_A2_EH) || p.iso3cd, name: p.romnam || p.NAME_EN || p.NAME,
        aliases: [...new Set([p.iso3cd, p.romnam, p.maplab, p.NAME, p.NAME_LONG, p.ADMIN, p.NAME_EN, p.NAME_RU, p.NAME_UK, p.NAME_ZH, p.ADM0_A3, p.ISO_A3_EH].filter(Boolean))], path: outline };
});
fs.writeFileSync(path.join(__dirname, '../src/assets/statisticsWorld.ts'), `// UN Geospatial boundaries. Generated by scripts/build-statistics-map.cjs.\n// Source: https://data-gis.unep-wcmc.org/server/rest/services/Hosted/UN_Boundaries/MapServer/6\n// Boundaries and names shown do not imply official endorsement or acceptance by the United Nations.\n// Source SHA256: ${crypto.createHash('sha256').update(source).digest('hex')}\nexport const STAT_WORLD: ReadonlyArray<{code:string;name:string;aliases:readonly string[];path:string}> = ${JSON.stringify(countries)};\n`);
console.log(`${countries.length} country outlines`);
